WITH enriched AS (SELECT id, supplier_name, country, city, rating, AVG(rating) OVER (ORDER BY rating ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS rating_avg_2_prior, SUM(rating) OVER (PARTITION BY country) AS country_sum_rating, SUM(rating) OVER w_grp AS cumulative_rating FROM suppliers WHERE country IN ('SG', 'DE') WINDOW w_grp AS (ORDER BY rating ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT id, supplier_name, city, rating, rating_avg_2_prior, cumulative_rating, CASE WHEN city RLIKE '^(London|Chiang Mai)$' THEN 'EXTENDED' WHEN city RLIKE '^(Bangkok|New York)$' THEN 'GROUP_A' ELSE 'OTHER_ZONE' END AS city_zone FROM enriched ORDER BY rating ASC, city_zone ASC;
